<script setup lang="ts">
import { useAdminWorkspace } from '../../composables/useAdminWorkspace'
import TaskOperationsPanel from '../../components/admin/TaskOperationsPanel.vue'
const { knowledgeTasks, taskSubject, taskQuery, taskUsage, knowledgeError, loading, fetchKnowledgeTasks, candidateSources, fetchedSource, searchKnowledgeSources, fetchCandidateSource, cancelKnowledgeTask, viewTaskUsage, retryKnowledgeTask, createKnowledgeCandidate, createHealthCheckTask } = useAdminWorkspace('tasks')
</script>
<template>
<div class="admin-module"><TaskOperationsPanel /><section class="workspace-panel"><h2>知识建设与采集任务</h2>          <div class="action-row"><el-input v-model="taskSubject" clearable placeholder="学科代码（可选，如 python）" /><el-button :loading="loading.knowledgeTasks" @click="createHealthCheckTask">排队巡检</el-button><el-button :loading="loading.knowledgeTasks" @click="fetchKnowledgeTasks">刷新任务</el-button></div>
          <div class="action-row"><el-input v-model="taskQuery" clearable maxlength="128" placeholder="待补充知识点或资料主题" /><el-button :loading="loading.knowledgeTasks" @click="searchKnowledgeSources">搜索候选来源</el-button></div>
          <p class="admin-evidence-note">候选来源和抓取正文仅供管理员审阅，不会自动进入公开知识库。</p>
          <div v-if="knowledgeTasks.length" class="list-stack"><div v-for="task in knowledgeTasks" :key="task.id" class="list-card static"><strong>#{{ task.id }} · {{ task.operation_type }}</strong><span>{{ task.subject || '全部学科' }} · {{ task.status }} · {{ task.current_step }}</span><span v-if="task.error_code">错误：{{ task.error_code }}</span><span v-if="typeof task.result?.issues_total === 'number'">巡检发现 {{ task.result.issues_total }} 项待处理问题</span><el-button v-if="['QUEUED', 'RUNNING'].includes(task.status)" size="small" @click="cancelKnowledgeTask(task)">取消</el-button><el-button size="small" @click="viewTaskUsage(task)">用量记录</el-button><el-button v-if="task.status === 'FAILED'" size="small" @click="retryKnowledgeTask(task)">重试任务</el-button><div v-for="(source, index) in candidateSources(task)" :key="source.url" class="admin-evidence-note"><a :href="source.url" target="_blank" rel="noreferrer">{{ source.title || source.url }}</a><span> {{ source.summary }}</span><el-button size="small" :loading="loading.knowledgeTasks" @click="fetchCandidateSource(task, index)">抓取正文</el-button></div><details v-if="fetchedSource(task)"><summary>查看候选正文：{{ fetchedSource(task)?.title }}</summary><pre>{{ fetchedSource(task)?.content }}</pre><el-button size="small" :loading="loading.candidates" @click="createKnowledgeCandidate(task)">转为候选知识</el-button></details></div></div>
<details v-if="taskUsage"><summary>调用与预算预留</summary><pre>{{ taskUsage }}</pre></details><p v-if="knowledgeError" role="alert">{{ knowledgeError }}</p></section></div>
</template>
<style src="./admin.css"></style>
